using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct CombatantId : IEquatable<CombatantId>, IComparable<CombatantId>
    {
        public Guid Value { get; }

        public CombatantId(Guid value)
        {
            Value = value;
        }

        public static CombatantId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static CombatantId NewRandom() => new CombatantId(Guid.NewGuid());

        public static CombatantId Parse(string text) => new CombatantId(Guid.Parse(text));

        public static bool TryParse(string text, out CombatantId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new CombatantId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(CombatantId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is CombatantId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(CombatantId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(CombatantId left, CombatantId right) => left.Equals(right);

        public static bool operator !=(CombatantId left, CombatantId right) => !left.Equals(right);
    }
}
